import { existsSync } from "node:fs";
import { writeFile } from "node:fs/promises";
import { EDITIONS, type EditionId } from "../../src/characters/figures";
import { fromRepo, paths, toPublic, toRepo } from "../tripo/env";
import { c, log, table } from "../tripo/log";
import { loadManifest } from "../tripo/manifest";
import { gameFileBase } from "../tripo/pipeline";
import { inspectGlb } from "./glb";

/**
 * Writes src/characters/asset-manifest.json — the only bridge between generated files and the Remotion bundle.
 * A figure is listed only after its GLB parsed cleanly, so a broken download can never reach a render.
 */
export const writeAssetManifest = async () => {
  const manifest = await loadManifest();
  const local = (key: string, name: string) => {
    const rel = manifest.tasks[key]?.outputs?.[name];
    return rel && existsSync(fromRepo(rel)) ? fromRepo(rel) : null;
  };

  const concepts: Record<string, string | null> = {};
  for (const id of ["master", ...EDITIONS.map((e) => e.id)]) {
    const f = local(`concept:${id}`, "image");
    concepts[id] = f ? toPublic(f) : null;
  }

  const figures: Record<string, unknown> = {};
  const rows: string[][] = [];
  let strategy: "per-edition" | "shared-master" | "none" = "none";
  for (const e of EDITIONS) {
    const own = local(`model:${e.id}`, "model");
    const shared = local("model:master", "model");
    const file = own ?? shared;
    if (!file) {
      figures[e.id] = null;
      rows.push([e.id, c.yellow("missing"), "—", "—", "procedural stand-in"]);
      continue;
    }
    strategy = own ? "per-edition" : strategy === "none" ? "shared-master" : strategy;
    const report = await inspectGlb(file);
    const preview = local(own ? `model:${e.id}` : "model:master", "preview");
    if (!report.ok) {
      figures[e.id] = null;
      rows.push([e.id, c.red("FAILED"), String(report.triangles), "—", report.problems.join("; ")]);
      continue;
    }
    figures[e.id] = {
      glb: toPublic(file),
      preview: preview ? toPublic(preview) : null,
      taskId: manifest.tasks[own ? `model:${e.id}` : "model:master"]?.task_id ?? null,
      shared: !own,
      triangles: report.triangles,
      textures: report.textures.length,
      bounds: report.bounds,
    };
    rows.push([e.id, c.green("ok"), String(report.triangles), report.size.map((s) => s.toFixed(3)).join(" × "), toRepo(file)]);
  }

  // Game assets: rigged + animated GLBs (skin, joints and clips verified).
  const game: Record<string, unknown> = {};
  const gameRows: string[][] = [];
  for (const e of EDITIONS) {
    const rigged = local(`game-rig:${e.id}`, "model");
    // all retarget batches merged into one GLB (scripts/convert/merge-clips.ts); else the first batch alone
    const mergedFile = `${gameFileBase(e.id, "animated")}.glb`;
    const animated = existsSync(mergedFile) ? mergedFile : local(`game-anim:${e.id}`, "model");
    if (!rigged && !animated) {
      game[e.id] = null;
      continue;
    }
    const entry: Record<string, unknown> = { tpose: local(`game-pose:${e.id}`, "image") ? toPublic(local(`game-pose:${e.id}`, "image")!) : null };
    for (const [name, file] of [
      ["rigged", rigged],
      ["animated", animated],
    ] as const) {
      if (!file) continue;
      if (!file.endsWith(".glb")) {
        entry[name] = { file: toPublic(file), verified: false, note: "FBX — inspect in a DCC tool / engine" };
        continue;
      }
      const r = await inspectGlb(file);
      const ok = r.ok && r.skins > 0 && (name === "rigged" || r.animations.length > 0);
      entry[name] = { glb: toPublic(file), ok, joints: r.joints, triangles: r.triangles, animations: r.animations, bounds: r.bounds, problems: r.problems };
      gameRows.push([
        e.id,
        name,
        ok ? c.green("ok") : c.red("FAILED"),
        `${r.skins} skin · ${r.joints} joints`,
        r.animations.map((a) => `${a.name} ${a.duration}s`).join(", ") || "—",
      ]);
    }
    game[e.id] = entry;
  }

  const out = {
    $comment: "Generated by scripts/qc/asset-manifest.ts — do not edit by hand.",
    generatedAt: new Date().toISOString(),
    strategy,
    concepts,
    figures: figures as Record<EditionId, unknown>,
    game,
  };
  await writeFile(paths.assetManifest, JSON.stringify(out, null, 2) + "\n");
  console.log();
  table(rows, ["edition", "glb", "triangles", "size (x × y × z)", "file"]);
  if (gameRows.length) {
    console.log();
    table(gameRows, ["edition", "game asset", "qc", "skeleton", "animations"]);
  }
  log.ok(`wrote ${toRepo(paths.assetManifest)}`);
  return out;
};
